"""Render the generated achievement-diary package layout."""

from __future__ import annotations


def family_module_source(family_block: str) -> str:
    return (
        '"""Generated by ``tools/generate_achievement_diary_data.py``.\n'
        'Do not hand-edit."""\n\n'
        "from __future__ import annotations\n\n"
        "from .contract import (\n"
        "    DiaryCondition,\n"
        "    DiaryFamily,\n"
        "    DiaryLamp,\n"
        "    DiaryTask,\n"
        "    DiaryTier,\n"
        ")\n\n\n"
        f"FAMILY = {family_block}\n"
    )


def aggregator_source(
    family_ids: tuple[str, ...], kept_total: int, total_cutoff_tasks: int
) -> str:
    imports = "\n".join(
        (
            f"from .achievement_diaries.{family_id} import FAMILY "
            f"as _{family_id}_family"
        )
        for family_id in family_ids
    )
    families = "\n".join(
        f"    _{family_id}_family," for family_id in family_ids
    )
    return (
        '"""Generated by ``tools/generate_achievement_diary_data.py``. '
        "Do not hand-edit.\n\n"
        "Darkan's achievement classes and rev-727 cache enum 3483 own task "
        "identity,\n"
        "original tier membership, names, descriptions and ordinary "
        "requirements.\n"
        "Regional rows are curated into twelve-task AnkiScape tiers; "
        "cross-tier\n"
        "placements and generic progression anchors are explicitly labelled. "
        "Pinned\n"
        "pre-cutoff wiki revisions are corroboration only. Ordinary "
        "requirements\n"
        "are shown as access gates and never complete a deed. "
        "Un-curated deeds are\n"
        "dormant: visible, incomplete, and excluded from automatic "
        "completion.\n\n"
        f"Named task rows: {kept_total}; designed cutoff denominator: "
        f'{total_cutoff_tasks}."""\n\n'
        "from __future__ import annotations\n\n"
        "from .achievement_diaries.contract import (\n"
        "    DiaryCondition,\n"
        "    DiaryFamily,\n"
        "    DiaryLamp,\n"
        "    DiaryTask,\n"
        "    DiaryTier,\n"
        ")\n"
        f"{imports}\n"
        "from .achievement_diaries.equipment import (\n"
        "    diary_equipment_data_as_dict as "
        "_diary_equipment_data_as_dict,\n"
        ")\n\n"
        "# PLACEHOLDER(achievement_diaries.misc_coin_reward): miscellaneous "
        "rewards use\n"
        "# the cache-proven 100-coin floor multiplied by completion ordinal. "
        "The exact\n"
        "# period curve needs the server payout routine or decoded completion "
        "script.\n\n\n"
        "DIARY_FAMILIES = (\n"
        f"{families}\n"
        ")\n\n"
        "diary_equipment_data_as_dict = _diary_equipment_data_as_dict\n"
        "diary_equipment_data_as_dict.__module__ = __name__\n\n"
        "__all__ = [\n"
        '    "annotations",\n'
        '    "DiaryCondition",\n'
        '    "DiaryFamily",\n'
        '    "DiaryLamp",\n'
        '    "DiaryTask",\n'
        '    "DiaryTier",\n'
        '    "DIARY_FAMILIES",\n'
        '    "diary_equipment_data_as_dict",\n'
        "]\n"
    )


def equipment_module_source(equipment_rows: str) -> str:
    return (
        '"""Generated by ``tools/generate_achievement_diary_data.py``.\n'
        'Do not hand-edit."""\n\n'
        "from __future__ import annotations\n\n\n"
        "def diary_equipment_data_as_dict() -> dict:\n"
        '    """Register the 32 tier reward items as real wearable '
        "equipment.\n\n"
        "    Without this the whole family would be inert: every tier hands "
        "over an\n"
        "    item that the equipment table has never heard of. The generated "
        "table is\n"
        "    built from the emulator config and must not be hand-edited, so "
        "these rows\n"
        "    join through the same per-family seam Barrows and the penguin "
        "ring use.\n"
        '    """\n\n'
        "    from ..equipment_data import EquipmentBonuses, EquipmentItem\n\n"
        "    return {\n" + equipment_rows + "\n    }\n"
    )


def catalog_outputs(
    family_sources: dict[str, str],
    kept_total: int,
    total_cutoff_tasks: int,
    equipment_rows: str,
) -> dict[str, str]:
    family_ids = tuple(family_sources)
    outputs = {
        "achievement_diary_catalog.py": aggregator_source(
            family_ids, kept_total, total_cutoff_tasks
        ),
        "achievement_diaries/__init__.py": "",
    }
    outputs.update(
        (f"achievement_diaries/{family_id}.py", source)
        for family_id, source in family_sources.items()
    )
    outputs["achievement_diaries/equipment.py"] = equipment_module_source(
        equipment_rows
    )
    return outputs
